<?php
require_once __DIR__ . '/app.php'; require_login(); verify_csrf(); if($_SERVER['REQUEST_METHOD']!=='POST') redirect('explore.php'); $me=current_user(); $target=(int)($_POST['user_id']??0); $mode=(($_POST['mode']??'follow')==='unfollow')?'unfollow':'follow';
if($target>0 && $target!== (int)$me['id']) { if($mode==='follow') { $stmt=$conn->prepare('INSERT IGNORE INTO follows (follower_id,followed_id) VALUES (?,?)');$stmt->bind_param('ii',$me['id'],$target);$stmt->execute();flash('You are now following this person.'); } else { $stmt=$conn->prepare('DELETE FROM follows WHERE follower_id=? AND followed_id=?');$stmt->bind_param('ii',$me['id'],$target);$stmt->execute();flash('You unfollowed this person.'); } }
$back=$_SERVER['HTTP_REFERER']??'explore.php'; if(!str_starts_with($back, '/') && !str_starts_with($back, 'http')) $back='explore.php'; if(str_starts_with($back,'http') && parse_url($back,PHP_URL_HOST)!==($_SERVER['HTTP_HOST']??'')) $back='explore.php'; redirect($back);
